1	#!/usr/bin/env bun
2	/**
3	 * resolve_issue_branch.ts — says which branch a run should check out, if any.
4	 *
5	 * Branches are created when work is committed, not when a run starts. Most runs
6	 * never commit: a run that reports a CI failure, confirms a merge, or closes an
7	 * issue produces no code. Creating a branch for those left one behind per run,
8	 * and the repository had accumulated 72 of them.
9	 *
10	 * Deciding by what a run does rather than by which agent it is matters. Agents
11	 * are the adopter's to edit, rename and add to, so nothing here may key off an
12	 * agent's name — a branch appears when something is committed, whoever committed
13	 * it.
14	 *
15	 * Usage:
16	 *   resolve_issue_branch.ts --repo owner/name --issue 12
17	 *
18	 * Writes `branch=<name-or-empty>` to $GITHUB_OUTPUT. Empty means start from the
19	 * base branch; `commit_and_push` names a new branch if the run turns out to need
20	 * one.
21	 */
22	import { appendFileSync } from "node:fs";
23	import { parseArgs } from "node:util";
24	import { collectIssueBranches, resumableBranch } from "../../adapters/github/issue-branches.ts";
25	
26	import { defineScript } from "./lib/script-ref.ts";
27	
28	export interface ResolveIssueBranchArgs {
29	  repo: string;
30	  issue: string;
31	}
32	
33	export const ref = defineScript<ResolveIssueBranchArgs>(import.meta.url);
34	
35	function log(message: string): void {
36	  console.error(`[atomaton-issue-branch] ${message}`);
37	}
38	
39	function main(): void {
40	  const { values } = parseArgs({
41	    args: Bun.argv.slice(2),
42	    options: { repo: { type: "string" }, issue: { type: "string" } },
43	  });
44	
45	  const repo = (values.repo ?? "").trim();
46	  const issue = Number(values.issue);
47	  const githubOutput = process.env.GITHUB_OUTPUT;
48	
49	  // Never fails the run. A run that cannot resolve its branch should start on the
50	  // base and let `commit_and_push` sort it out, not stop before the agent has
51	  // said anything.
52	  let branch = "";
53	  if (repo && Number.isInteger(issue) && issue > 0) {
54	    // An unread list is safely "start from the base branch" HERE, and only here:
55	    // resuming nothing costs a run its previous work tree, while creating a branch
56	    // blind risks an existing one. `collectIssueBranches` says which answer it is
57	    // giving so the two callers can differ.
58	    const listed = collectIssueBranches(repo, issue);
59	    if (listed.known) branch = resumableBranch(listed.branches);
60	    else log(`${listed.why}; staying on the base branch`);
61	  } else {
62	    log("missing --repo or --issue; staying on the base branch");
63	  }
64	
65	  log(branch ? `resuming ${branch}` : "no branch to resume; starting from the base branch");
66	  if (githubOutput) appendFileSync(githubOutput, `branch=${branch}\n`);
67	}
68	
69	if (import.meta.main) main();

