186	/**
187	 * The name of the branch a run should continue, or `""` to stay on the base.
188	 *
189	 * The rule is `ordinalToResume`; this turns its answer back into the name the
190	 * caller checks out. `""` rather than `undefined` because the one caller writes it
191	 * straight to `$GITHUB_OUTPUT`, where an absent value and an empty one are the same
192	 * thing and the empty one is what the step's condition reads.
193	 */
194	export function resumableBranch(branches: readonly IssueBranch[]): string {
195	  const ordinal = ordinalToResume(branches);
196	  return branches.find((branch) => branch.ordinal === ordinal)?.name ?? "";
197	}

